import { useState, useEffect } from 'react';

/**
 * Custom React hook to debounce any fast-changing value.
 * @param value The raw input value
 * @param delay Milliseconds to delay update (default: 300ms)
 */
export function useDebounceValue<T>(value: T, delay = 300): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type Job struct {
	ID    int
	Data  string
}

type Result struct {
	JobID  int
	Output string
	Err    error
}

func worker(ctx context.Context, id int, jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	defer wg.Done()
	for {
		select {
		case <-ctx.Done():
			return
		case job, ok := <-jobs:
			if !ok {
				return
			}
			// Process job
			res := Result{
				JobID:  job.ID,
				Output: fmt.Sprintf("Worker %d completed %s", id, job.Data),
			}
			results <- res
		}
	}
}
